('42MFC1#1#3#2#10', 'Fitur menilai-ppkp-bawahan', 'diakses oleh atasasn yang punya bawahan (menilai-ppkp-bawahan).\n\nseterusnya butuh persetujuan bawahan di url nilai-kpi-anda', 0, 'Mw==', 'MTA=', '5', 1, '2024-09-09 19:35:11', '2024-09-09 19:35:11', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('42MFC1#1#3#2#11', 'Setting PPKP Karyawan', 'dapat akses dengan jenis_jabatan =\'f\'\n\nmengatur ppkp semua karyawan', 0, 'Mw==', 'MTA=', '5', 1, '2024-09-09 19:48:22', '2024-09-09 19:48:22', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('42MFC1#1#3#2#12', 'Fitur Report Penilaian', 'dapat akses dengan jenis_jabatan =\'f\'', 0, 'Mw==', 'MTA=', '5', 1, '2024-09-09 20:04:08', '2024-09-09 20:04:08', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('42MFC1#1#3#2#2', 'tahapan Setting Target', 'user tanpa bawahan hanya dapat mengakses penilaian saja\nuser dengan bawahan dapat menambahkan setting target kepada setiap bawahan', 0, 'Mw==', '', '5', 1, '2024-09-08 21:36:38', '2024-09-08 21:36:38', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('42MFC1#1#3#2#2#1', 'Indikator Kinerja Utama	(tidak muncul)', 'http://localhost:8401/api/v1/pegawai/rencana-kerja/kpi-subsatker?tahun=2024&semester=1&isAdmin=0&kode_satker_cur=12000\n\ndisebabkan oleh, data pada position id atau fs tidak sesuai dengan kondisi. \n/rencana-kerja/kpi-subsatker\n\nconst { position_id } = req.userData.position;\n    const nopeg = req.userData.employeeID;\n    const { fs } = req.userData.position;', 0, 'Mw==', '', '6', 1, '2024-09-09 00:39:54', '2024-09-09 02:15:53', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('42MFC1#1#3#2#2#2', 'Akses data setting target', 'http://localhost:8401/api/v1/pegawai/rencana-kerja/assignment?tahun=2024&noPeg=9823120371\ndibedakan berdasarkan tipe seperti KPI Tambahan, KPI Subsatker dll', 0, 'Mw==', '', '6', 1, '2024-09-09 01:00:01', '2024-09-09 01:07:43', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('42MFC1#1#3#2#2#3', 'Key Performance Index (Tidak Muncul)', 'Bobot tidak tersedia\nhttp://localhost:8401/api/v1/pegawai/rencana-kerja/assignment/bobot?jj=null&fs=F\n\ndisebabkan payload (9723120372)\njj: null\nfs: F,\ncontoh yang benar :\njj: 5C\nfs: F', 0, 'Mw==', 'MTA=', '6', 1, '2024-09-09 17:42:41', '2024-09-09 17:54:20', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('42MFC1#1#3#2#3', 'Tingkatan User', 'SELECT jenis_jabatan,jenjang_jabatan e FROM [cisea.bamedika.co.id-ppkp].dbo.tb_pegawai x\ngroup by jenis_jabatan,jenjang_jabatan\n\nF	\nF	2B\nF	3A\nF	4B\nF	4C\nF	5A\nF	5B\nF	5C\nS	\nS	2A\nS	2B\nS	3C\nS	4B\nS	5A', 0, 'Mw==', '', '5', 1, '2024-09-09 00:33:56', '2024-09-09 00:33:56', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('42MFC1#1#3#2#4', 'Fitur PPKP Anda', 'Identitas Pegawai tidak muncul disebabkan karena data pada [cisea.bamedika.co.id-ppkp].dbo.tb_pegawai tidak tersedia, namun di data login user cisea tersedia', 0, 'Mw==', 'MTA=', '5', 1, '2024-09-09 17:57:29', '2024-09-09 18:10:31', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('42MFC1#1#3#2#5', 'Fitur coaching bawahan', 'Atasan (2B / F|S) menambahkan arahan kepada setiap bawahan, untuk mencapai potensi maksimalnya (Formulir 2C)\nproses ini dibutuhkan persetujuan bahawan dengan cara mengakses coaching pribadi bawahan\n\nfitur ini tidak terbatas oleh open close date', 0, 'Mw==', 'MTA=', '5', 1, '2024-09-09 18:13:30', '2024-09-09 18:18:59', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
