INSERT INTO `judul` (`kdJudul`, `judul`, `ringkasan`, `publikasi`, `kdMember`, `kdMemberSub`, `tingkat`, `aktif`, `created_at`, `updated_at`, `jsCatatan`, `jsFEntri`, `dpCatatan`, `dpFEntri`) VALUES
('8MFC1#2#1#3#5#1', '(ol)Constraint Validation API', 'pattern (patternMismatch), Nilai harus sesuai dengan pola (regular expression).\nmin (rangeUnderflow), Nilai harus sama dengan atau lebih besar dari nilai atribut ini.\nmax (rangeOverflow), Nilai harus sama dengan atau lebih kecil dari nilai atribut ini.\nrequired (valueMissing), Nilai harus diisi (tidak boleh kosong).\nstep (stepMismatch), Nilai harus dalam kelipatan nilai yang didefinisikan relatif terhadap nilai minimal (min) dan harus lebih besar darinya.\nminlength (tooShort), Panjang karakter teks harus sama dengan atau lebih besar dari nilai atribut ini.\nmaxlength (tooLong), Panjang karakter teks harus sama dengan atau lebih kecil dari nilai atribut ini.', 0, 'Mw==', '', '6', 1, '2024-07-30 16:27:45', '2024-07-30 16:27:45', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#1#3#5#2', 'example Constraint Validation API', 'HTML :\n<pre id=\"log\">Validation failures logged here...</pre>\n<input\n  type=\"text\"\n  id=\"userInput\"\n  placeholder=\"How do you feel?\"\n  minlength=\"2\" />\n<button id=\"checkButton\">Validate input</button>\n\nCSS: \ninput:invalid {\n  border: red solid 3px;\n}\n\nJS :\nconst userInput = document.getElementById(\"userInput\");\nconst checkButton = document.getElementById(\"checkButton\");\nconst logElement = document.getElementById(\"log\");\n\nfunction log(text) {\n  logElement.innerText = text;\n}\n\nconst check = (input) => {\n  // Handle cases where input is too vague\n  if (input.value == \"good\" || input.value == \"fine\") {\n    input.setCustomValidity(`\"${input.value}\" is not a feeling.`);\n  } else {\n    // An empty string resets the custom validity state\n    input.setCustomValidity(\"\");\n  }\n};\n\nuserInput.addEventListener(\"input\", () => {\n  check(userInput);\n});\n\nconst validateInput = () => {\n  userInput.reportValidity();\n  if (userInput.validity.customError) {\n    // We can handle custom validity states here\n    log(\"Custom validity error: \" + userInput.validationMessage);\n  } else {\n    log(userInput.validationMessage);\n  }\n};\n\ncheckButton.addEventListener(\"click\", validateInput);', 0, 'Mw==', '', '6', 1, '2024-07-30 16:29:05', '2024-07-30 16:29:05', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#1#3#5#3', 'Tidak Memerlukan Validasi', 'HTML :\n<form novalidate>\n  <!-- Beberapa form control disembunyikan -->\n \n  <button>Kirim</button>\n</form>\n\n<form>\n  <!-- Beberapa form control disembunyikan -->\n \n  <button formnovalidate>Kirim</button>\n</form>', 0, 'Mw==', '', '6', 1, '2024-07-30 16:31:47', '2024-07-30 16:31:47', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#1#3#5#4', 'Tidak Memerlukan Validasi', 'HTML :\n<form novalidate>\n  <!-- Beberapa form control disembunyikan -->\n \n  <button>Kirim</button>\n</form>\n\n<form>\n  <!-- Beberapa form control disembunyikan -->\n \n  <button formnovalidate>Kirim</button>\n</form>', 0, 'Mw==', '', '6', 1, '2024-07-30 16:31:48', '2024-07-30 16:31:48', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#1#3#6', 'Auto Completion / Autofill', '-', 0, 'Mw==', '', '5', 1, '2024-07-30 16:37:39', '2024-07-30 16:37:39', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#1#3#6#1', 'Browser dapat mengidentifikasi sebuah input berdasarkan nilai dari atributnya (name, id)', '<label for=\"email\">Email</label>\n<input type=\"email\" name=\"email\" id=\"email\">\n\n\n<form>\n      <div class=\"form-group\">\n        <label for=\"name\">Nama</label>\n        <input type=\"text\" name=\"name\" id=\"name\" autocomplete=\"name\" />\n      </div>\n      <div class=\"form-group\">\n        <label for=\"telephone\">Telepon</label>\n        <input type=\"tel\" name=\"telephone\" id=\"telephone\" autocomplete=\"tel\" />\n      </div>\n      <div class=\"form-group\">\n        <label for=\"email\">Email</label>\n        <input type=\"email\" name=\"email\" id=\"email\" autocomplete=\"email\" />\n      </div>\n      <div class=\"form-group\">\n        <label for=\"password\">Password</label>\n        <input\n          type=\"password\"\n          name=\"password\"\n          id=\"password\"\n          autocomplete=\"new-password\"\n        />\n      </div>\n      <div class=\"form-group\">\n        <label for=\"password-confirm\">Konfirmasi Password</label>\n        <input\n          type=\"password\"\n          name=\"password-confirm\"\n          id=\"password-confirm\"\n          autocomplete=\"new-password\"\n        />\n      </div>\n\n      <div class=\"form-group\">\n        <button class=\"btn\">Daftar</button>\n      </div>\n    </form>', 0, 'Mw==', '', '6', 1, '2024-07-30 16:38:06', '2024-07-30 16:40:19', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#1#3#6#2', '(ol)Jenis autocomplete (Type Input)', 'autocomplete=\"email\"\nautocomplete=\"tel\"\nautocomplete=\"new-password\"\nautocomplete=\"off\" jika tidak ingin disarankan', 0, 'Mw==', '', '6', 1, '2024-07-30 16:41:51', '2024-07-30 16:41:51', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#1#3#7', '(ol)Memperjelas dengan Input dengan Fokus', '<div class=\"form-group\">\n        <label for=\"name\">Nama</label>\n        <input type=\"text\" name=\"name\" id=\"name\" />\n      </div>\n\nCSS:\ninput:focus-visible {\n  appearance: none;\n  outline: none;\n\n  box-shadow: 0 0 0 6px rgb(30, 144, 255, 0.65);\n}\n\nlabel:has(+ input:focus-visible) {\n  font-weight: bold;\n}\n\nlabel,\ninput,\nbutton {\n  font-size: 1rem;\n\n  transition: all 150ms linear;\n}', 0, 'Mw==', '', '5', 1, '2024-07-30 16:46:11', '2024-07-30 16:46:31', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#1#3#8', '(ol)Styling Form', 'Memperjelas dengan Fokus\nLebih Terbaca Saat Besar, default 13 px, untuk baiknya 1rem = 16px\nTampilkan dengan Layak, terkadang tidak jelas tempat inputnya\nMengubah Aksen, accent-color: salmon;\nInvalid State, input:invalid {  border: 1.5px solid red;}\nForm Control yang Sukar Diberi Gaya', 0, 'Mw==', '', '5', 1, '2024-07-30 16:49:07', '2024-07-30 17:03:10', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#1#3#8#1', '(ol)styling kompleks', 'Input checkbox.\nInput radio atau tombol radio.\nElemen input teks bertipe pencarian: <input type=\"search\">.', 0, 'Mw==', '', '6', 1, '2024-07-30 17:04:23', '2024-07-30 17:04:23', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#1#3#8#2', '(ol)elemen-elemen yang tidak bisa di-styling sama sekali', 'Elemen-elemen yang terlibat dalam pembuatan dropdown, yaitu <select>, <option>, <optgroup>, dan <datalist>.\nInput color.\nInput yang berkaitan dengan penanggalan, seperti <input type=\"datetime-local\">.\nElemen input bertipe range.\nElemen input untuk tipe data berkas.\nElemen <progress> dan <meter>.', 0, 'Mw==', '', '6', 1, '2024-07-30 17:04:39', '2024-07-30 17:04:39', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
