('8MFC1#2#1#3#9#1', 'membiarkan flex items membuat baris baru (flex-wrap)', '.container {\n  display: flex;\n  flex-wrap: wrap;\n\n  gap: 10px;\n}', 0, 'Mw==', '', '6', 1, '2024-07-30 17:13:05', '2024-07-30 17:14:10', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#1#3#9#2', 'wrapping atau auto filling pada baris baru', '.container {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, 200px);\n\n  gap: 10px;\n}\n\ngrid-template-columns: repeat(3, minmax(200px, 1fr));', 0, 'Mw==', '', '6', 1, '2024-07-30 17:14:07', '2024-07-31 00:07:21', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#1#3#9#3', 'layouting satu dimensi ( row / columns)', '.flex-container {\n  display: flex;\n  flex-direction: row;\n  flex-wrap: wrap;\n}', 0, 'Mw==', '', '6', 1, '2024-07-30 17:16:06', '2024-07-30 17:16:06', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#1#3#9#4', 'Peletakan Konfigurasi', 'HTML:\n\n<div class=\"container\">\n        <div style=\"background-color: lightsalmon\" class=\"box1\"></div>\n        <div style=\"background-color: lightblue\" class=\"box2\"></div>\n        <div style=\"background-color: lightgreen\" class=\"box3\"></div>\n      </div>\n\nCSS:\n.container {\n  display: flex;\n}\n\n.container > div {\n  height: 150px;\n}\n\n.container > div:nth-child(1) {\n  flex-grow: 0;\n  flex-shrink: 0;\n  flex-basis: 5em;\n}\n\n.container > div:nth-child(2) {\n  flex-grow: 1;\n}\n\n.container > div:nth-child(3) {\n  flex-grow: 0;\n  flex-shrink: 0;\n  flex-basis: 100px;\n}\n\n\n.container {\n  display: grid;\n  grid-template-columns: 5em auto 100px;\n  grid-template-rows: 100px 100px;\n}', 0, 'Mw==', '', '6', 1, '2024-07-30 17:17:18', '2024-07-30 17:17:58', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#1#3#9#5', 'space / gap grid', '.char-list {\n  margin-block: 1rem;\n \n  display: grid;\n  grid-template-columns: repeat(6, 1fr);\n \n  column-gap: 24px;\n  row-gap: 32px;\n}', 0, 'Mw==', '', '6', 1, '2024-07-30 17:28:55', '2024-07-30 17:28:55', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
