('8MFC1#2#2#2#1#1', '(html) Content dibagian atas btn', '<div id=\"dropdonwUl_\">\n                <button class=\"dropdown-btn\">\n                    <span>Framework</span>\n                    <span class=\"  arrowTop\"></span>\n                </button>\n                <ul class=\"dropdown-content dcTop\">\n                    <li style={{\"--delay\": 1}} ><a href=\"#\">React</a></li>\n                    <li><a href=\"#\">Angular</a></li>\n                    <li><a href=\"#\">Vue</a></li>\n                    <li><a href=\"#\">Svelte</a></li>\n                </ul>\n            </div>', 0, 'Mw==', '', '6', 1, '2024-07-08 19:25:33', '2024-07-13 00:15:01', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#2#2#1#2', '(html) content dibagian bawah btn', '<div id=\"dropdonwUl_\">\n                <button class=\"dropdown-btn\">\n                    <span>Framework</span>\n                    <span class=\"arrow\"></span>\n                </button>\n                <ul class=\"dropdown-content\">\n                    <li style={{\"--delay\": 1}} ><a href=\"#\">React</a></li>\n                    <li><a href=\"#\">Angular</a></li>\n                    <li><a href=\"#\">Vue</a></li>\n                    <li><a href=\"#\">Svelte</a></li>\n                </ul>\n            </div>', 0, 'Mw==', '', '6', 1, '2024-07-08 19:26:34', '2024-07-13 00:15:11', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#2#2#1#3', 'css', '#dropdonwUl_ {\n  max-width: 13em;\n  margin: 80px auto 0;\n  position: relative;\n  width: 100%;\n  & .dropdown-btn {\n    background: #1d1f24;\n    font-size: 18px;\n    width: 100%;\n    border: none;\n    color: #fff;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    padding: 0.7em 0.5em;\n    border-radius: 0.5em;\n    cursor: pointer;\n  }\n  \n  & ul{\n    padding: 0px 5px;\n    // background-color: lightblue; \n  }\n  & .arrow {\n    border-left: 5px solid transparent;\n    border-right: 5px solid transparent;\n    border-bottom: 6px solid #fff;\n    transition: transform ease-in-out 0.3s;\n    // ease-in-out ease-in\n  }\n  & .arrowTop {\n    border-left: 5px solid transparent;\n    border-right: 5px solid transparent; \n    transition: transform ease-in-out 0.3s; \n    border-top: 6px solid #fff;\n  }\n  & .dropdown-content {\n    list-style: none;\n    position: absolute;\n    top: 3.2em;\n    width: 100%;\n  }\n  .dcTop { \n    bottom: 3.2em !important;\n    top:unset; \n  }\n\n  & .dropdown-content li {\n    background: #2f3238;\n    border-radius: 0.5em;\n  }\n  & .dropdown-content li:hover {\n    background: #1d1f24;\n  }\n  & .dropdown-content li a {\n    display: block;\n    padding: 0.7em 0.5em;\n    color: #fff;\n    margin: 0.1em 0;\n    text-decoration: none;\n  }\n  & .dropdown-content {\n    /* ... */\n    visibility: hidden;\n  }\n  & .dropdown-btn:focus + .dropdown-content {\n    visibility: visible;\n  } \n  & .dropdown-btn:focus > .arrow {\n    transform: rotate(180deg);\n  } \n  & .dropdown-btn:focus > .arrowTop {\n    transform: rotate(180deg);\n  }  \n  \n  &.dropdown-content {\n    /* ... */\n    overflow: hidden;\n  } \n  & .dropdown-content li {\n    /* ... */\n    position: relative;\n    left: 100%;\n    transition: 0.5s;\n  }\n  & .dropdown-btn:focus + .dropdown-content li {\n    left: 0;\n  }\n  & .dropdown-content li {\n    /* ... */\n    transition-delay: calc(60ms * var(--delay));\n  }\n}', 0, 'Mw==', '', '6', 1, '2024-07-08 19:27:07', '2024-07-08 19:27:07', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
