('8MFC1#2#2#3#2#2', 'css', '.btn-round {\n  display: inline-block;\n  padding: .75rem 1.25rem;\n  // border-radius: 10rem;\n  color: #fff;\n  text-transform: uppercase;\n  font-size: 1rem;\n  letter-spacing: .15rem;\n  transition: all .3s;\n  position: relative;\n  overflow: hidden;\n  z-index: 1;\n  &:after {\n    content: \'\';\n    position: absolute;\n    bottom: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    background-color: map-get(_.$c, \'info\');\n    border-radius: 10rem;\n    z-index: -2;\n  }\n  &:before {\n    content: \'\';\n    position: absolute;\n    bottom: 0;\n    left: 0;\n    width: 0%;\n    height: 100%;\n    background-color: darken(map-get(_.$c, \'info\'), 15%);\n    transition: all .3s;\n    border-radius: 10rem;\n    z-index: -1;\n  }\n  &:hover {\n    color: #fff;\n    &:before {\n      width: 100%;\n    }\n  }\n}', 0, 'Mw==', '', '6', 1, '2024-07-08 20:49:58', '2024-07-08 20:49:58', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
