('8MFC1#2#2#3#3#1', '(html)html', '<div class=\"bblob\">\n                <button class=\"blob-btn\">\n                    Blob Button\n                    <span class=\"blob-btn__inner\">\n                    <span class=\"blob-btn__blobs\">\n                        <span class=\"blob-btn__blob\"></span>\n                        <span class=\"blob-btn__blob\"></span>\n                        <span class=\"blob-btn__blob\"></span>\n                        <span class=\"blob-btn__blob\"></span>\n                    </span>\n                    </span>\n                </button>\n            </div>', 0, 'Mw==', '', '6', 1, '2024-07-08 20:52:26', '2024-07-26 18:44:03', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#2#3#3#2', 'css', '$cyan: #0505A9;\n$dark: #FFFFFF;\n$borderW: 2px; \n.blob-btn {\n  margin-top: 50px;\n  text-align: center;\n  border-radius:30px;\n  $numOfBlobs: 4;\n  z-index: 1;\n  position: relative;\n  padding: 20px 46px;\n  margin-bottom: 30px;\n  text-align: center;\n  text-transform: uppercase;\n  color: $cyan;\n  font-size: 16px;\n  font-weight: bold;\n  background-color: transparent;\n  outline: none;\n  border: none;\n  transition: color 0.5s;\n  cursor: pointer;\n  border-radius:30px;\n  \n  &:before {\n    content: \"\";\n    z-index: 1;\n    position: absolute;\n    left: 0;\n    top: 0;\n    width: 100%;\n    height: 100%;\n    border: $borderW solid $cyan;\n    border-radius:30px;\n  }\n  \n  &:after {\n    content: \"\";\n    z-index: -2;\n    position: absolute;\n    left: $borderW*1.5;\n    top: $borderW*1.5;\n    width: 100%;\n    height: 100%;\n\n    transition: all 0.3s 0.2s;\n    border-radius:30px;\n  }\n  \n  &:hover {\n    color: $dark;\n    border-radius:30px;\n    \n    &:after {\n      transition: all 0.3s;\n      left: 0;\n      top: 0;\n      border-radius:30px;\n    }\n  }\n  \n  &__inner {\n    z-index: -1;\n    overflow: hidden;\n    position: absolute;\n    left: 0;\n    top: 0;\n    width: 100%;\n    height: 100%;\n    border-radius:30px;\n    background:#ffffff;\n  }\n  \n  // additional container created, because in FF blobs are breaking overflow:hidden of element with svg gooey filter\n  &__blobs {\n    position: relative;\n    display: block;\n    height: 100%;\n    filter: url(\'#goo\');\n  }\n  \n  &__blob {\n    position: absolute;\n    top: $borderW;\n    width: 100% / $numOfBlobs;\n    height: 100%;\n    background: $cyan;\n    border-radius: 100%;\n    transform: translate3d(0,150%,0) scale(1.7);\n    transition: transform 0.45s;\n    \n    @supports(filter: url(\'#goo\')) {\n      transform: translate3d(0,150%,0) scale(1.4);\n    }\n    \n    @for $i from 1 through $numOfBlobs {\n      &:nth-child(#{$i}) {\n        left: ($i - 1) * (120% / $numOfBlobs);\n        transition-delay: ($i - 1) * 0.08s;\n      }\n    }\n    \n    .blob-btn:hover & {\n      transform: translateZ(0) scale(1.7);\n       \n    }\n  }\n  \n}', 0, 'Mw==', '', '6', 1, '2024-07-08 20:52:29', '2024-07-08 21:01:42', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
