('8MFC1#2#2#3#4#2', 'css', '.btn-inline {\n  color: #FFF;\n  transition: all 0.3s;\n  position: relative;\n  line-height: 50px;\n  height: 50px;\n  text-align: center;\n  width: 250px;\n  cursor: pointer;\n}\n.btn-inline span {\n  transition: all 0.3s;\n}\n.btn-inline::before {\n  content: \'\';\n  position: absolute;\n  bottom: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  z-index: 1;\n  opacity: 0;\n  transition: all 0.3s;\n  border-top-width: 1px;\n  border-bottom-width: 1px;\n  border-top-style: solid;\n  border-bottom-style: solid;\n  border-top-color: rgba(255,255,255,0.5);\n  border-bottom-color: rgba(255,255,255,0.5);\n  transform: scale(0.1, 1);\n}\n.btn-inline:hover span {\n  letter-spacing: 2px;\n}\n.btn-inline:hover::before {\n  opacity: 1; \n  transform: scale(1, 1); \n}\n.btn-inline::after {\n  content: \'\';\n  position: absolute;\n  bottom: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  z-index: 1;\n  transition: all 0.3s;\n  background-color: rgba(255,255,255,0.1);\n}\n.btn-inline:hover::after {\n  opacity: 0; \n  transform: scale(0.1, 1);\n}', 0, 'Mw==', '', '6', 1, '2024-07-08 21:09:31', '2024-07-08 21:09:31', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
