('8MFC1#2#2#4#1#1', 'html', '<nav>\n                    <ul class=\"mcd-menu\">\n                        <li>\n                            <a href=\"\">\n                                <i class=\"fa fa-home\"></i>\n                                <strong>Home</strong>\n                                <small>sweet home</small>\n                            </a>\n                        </li>\n                        <li>\n                            <a href=\"\" class=\"active\">\n                                <i class=\"fa fa-edit\"></i>\n                                <strong>About us</strong>\n                                <small>sweet home</small>\n                            </a>\n                        </li>\n                        <li>\n                            <a href=\"\">\n                                <i class=\"fa fa-gift\"></i>\n                                <strong>Features</strong>\n                                <small>sweet home</small>\n                            </a>\n                        </li>\n                        <li>\n                            <a href=\"\">\n                                <i class=\"fa fa-globe\"></i>\n                                <strong>News</strong>\n                                <small>sweet home</small>\n                            </a>\n                        </li>\n                        <li>\n                            <a href=\"\">\n                                <i class=\"fa fa-comments-o\"></i>\n                                <strong>Blog</strong>\n                                <small>what they say</small>\n                            </a>\n                            <ul>\n                                <li><a href=\"#\"><i class=\"fa fa-globe\"></i>Mission</a></li>\n                                <li>\n                                    <a href=\"#\"><i class=\"fa fa-group\"></i>Our Team</a>\n                                    <ul>\n                                        <li><a href=\"#\"><i class=\"fa fa-female\"></i>Leyla Sparks</a></li>\n                                        <li>\n                                            <a href=\"#\"><i class=\"fa fa-male\"></i>Gleb Ismailov</a>\n                                            <ul>\n                                                <li><a href=\"#\"><i class=\"fa fa-leaf\"></i>About</a></li>\n                                                <li><a href=\"#\"><i class=\"fa fa-tasks\"></i>Skills</a></li>\n                                            </ul>\n                                        </li>\n                                        <li><a href=\"#\"><i class=\"fa fa-female\"></i>Viktoria Gibbers</a></li>\n                                    </ul>\n                                </li>\n                                <li><a href=\"#\"><i class=\"fa fa-trophy\"></i>Rewards</a></li>\n                                <li><a href=\"#\"><i class=\"fa fa-certificate\"></i>Certificates</a></li>\n                            </ul>\n                        </li>\n                        <li>\n                            <a href=\"\">\n                                <i class=\"fa fa-picture-o\"></i>\n                                <strong>Portfolio</strong>\n                                <small>sweet home</small>\n                            </a>\n                        </li>\n                        <li>\n                            <a href=\"\">\n                                <i class=\"fa fa-envelope-o\"></i>\n                                <strong>Contacts</strong>\n                                <small>drop a line</small>\n                            </a>\n                        </li>\n                            \n                    </ul>\n                </nav>', 0, 'Mw==', '', '6', 1, '2024-07-08 21:14:25', '2024-07-08 21:14:43', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#2#4#1#2', 'css', '.mcd-menu {\n  list-style: none;\n  padding: 0;\n  margin: 0;\n  background: #FFF;\n  /*height: 100px;*/\n  border-radius: 2px;\n  -moz-border-radius: 2px;\n  -webkit-border-radius: 2px;\n  \n  /* == */\n  width: 250px;\n  /* == */\n}\n.mcd-menu li {\n  position: relative;\n  /*float:left;*/\n}\n.mcd-menu li a {\n  display: block;\n  text-decoration: none;\n  padding: 12px 20px;\n  color: #777;\n  /*text-align: center;\n  border-right: 1px solid #E7E7E7;*/\n  \n  /* == */\n  text-align: left;\n//   height: 36px;\n  position: relative;\n  border-bottom: 1px solid #EEE;\n  /* == */\n}\n.mcd-menu li a i {\n  /*display: block;\n  font-size: 30px;\n  margin-bottom: 10px;*/\n  \n  /* == */\n  float: left;\n  font-size: 20px;\n  margin: 0 10px 0 0;\n  /* == */\n  \n}\n/* == */\n.mcd-menu li a p {\n  float: left;\n  margin: 0 ;\n}\n/* == */\n\n.mcd-menu li a strong {\n  display: block;\n  text-transform: uppercase;\n}\n.mcd-menu li a small {\n  display: block;\n  font-size: 10px;\n}\n\n.mcd-menu li a i, .mcd-menu li a strong, .mcd-menu li a small {\n  position: relative;\n  \n  transition: all 300ms linear;\n  -o-transition: all 300ms linear;\n  -ms-transition: all 300ms linear;\n  -moz-transition: all 300ms linear;\n  -webkit-transition: all 300ms linear;\n}\n.mcd-menu li:hover > a i {\n    opacity: 1;\n    -webkit-animation: moveFromTop 300ms ease-in-out;\n    -moz-animation: moveFromTop 300ms ease-in-out;\n    -ms-animation: moveFromTop 300ms ease-in-out;\n    -o-animation: moveFromTop 300ms ease-in-out;\n    animation: moveFromTop 300ms ease-in-out;\n}\n.mcd-menu li:hover a strong {\n    opacity: 1;\n    -webkit-animation: moveFromLeft 300ms ease-in-out;\n    -moz-animation: moveFromLeft 300ms ease-in-out;\n    -ms-animation: moveFromLeft 300ms ease-in-out;\n    -o-animation: moveFromLeft 300ms ease-in-out;\n    animation: moveFromLeft 300ms ease-in-out;\n}\n.mcd-menu li:hover a small {\n    opacity: 1;\n    -webkit-animation: moveFromRight 300ms ease-in-out;\n    -moz-animation: moveFromRight 300ms ease-in-out;\n    -ms-animation: moveFromRight 300ms ease-in-out;\n    -o-animation: moveFromRight 300ms ease-in-out;\n    animation: moveFromRight 300ms ease-in-out;\n}\n\n.mcd-menu li:hover > a {\n  color: #e67e22;\n}\n.mcd-menu li a.active {\n  position: relative;\n  color: #e67e22;\n  border:0;\n  /*border-top: 4px solid #e67e22;\n  border-bottom: 4px solid #e67e22;\n  margin-top: -4px;*/\n  box-shadow: 0 0 5px #DDD;\n  -moz-box-shadow: 0 0 5px #DDD;\n  -webkit-box-shadow: 0 0 5px #DDD;\n  \n  /* == */\n  border-left: 4px solid #e67e22;\n  border-right: 4px solid #e67e22;\n  margin: 0 -4px;\n  /* == */\n}\n.mcd-menu li a.active:before {\n  content: \"\";\n  position: absolute;\n  /*top: 0;\n  left: 45%;\n  border-top: 5px solid #e67e22;\n  border-left: 5px solid transparent;\n  border-right: 5px solid transparent;*/\n  \n  /* == */\n  top: 42%;\n  left: 0;\n  border-left: 5px solid #e67e22;\n  border-top: 5px solid transparent;\n  border-bottom: 5px solid transparent;\n  /* == */\n}\n\n/* == */\n.mcd-menu li a.active:after {\n  content: \"\";\n  position: absolute;\n  top: 42%;\n  right: 0;\n  border-right: 5px solid #e67e22;\n  border-top: 5px solid transparent;\n  border-bottom: 5px solid transparent;\n}\n/* == */\n\n@-webkit-keyframes moveFromTop {\n    from {\n        opacity: 0;\n        -webkit-transform: translateY(200%);\n        -moz-transform: translateY(200%);\n        -ms-transform: translateY(200%);\n        -o-transform: translateY(200%);\n        transform: translateY(200%);\n    }\n    to {\n        opacity: 1;\n        -webkit-transform: translateY(0%);\n        -moz-transform: translateY(0%);\n        -ms-transform: translateY(0%);\n        -o-transform: translateY(0%);\n        transform: translateY(0%);\n    }\n}\n@-webkit-keyframes moveFromLeft {\n    from {\n        opacity: 0;\n        -webkit-transform: translateX(200%);\n        -moz-transform: translateX(200%);\n        -ms-transform: translateX(200%);\n        -o-transform: translateX(200%);\n        transform: translateX(200%);\n    }\n    to {\n        opacity: 1;\n        -webkit-transform: translateX(0%);\n        -moz-transform: translateX(0%);\n        -ms-transform: translateX(0%);\n        -o-transform: translateX(0%);\n        transform: translateX(0%);\n    }\n}\n@-webkit-keyframes moveFromRight {\n    from {\n        opacity: 0;\n        -webkit-transform: translateX(-200%);\n        -moz-transform: translateX(-200%);\n        -ms-transform: translateX(-200%);\n        -o-transform: translateX(-200%);\n        transform: translateX(-200%);\n    }\n    to {\n        opacity: 1;\n        -webkit-transform: translateX(0%);\n        -moz-transform: translateX(0%);\n        -ms-transform: translateX(0%);\n        -o-transform: translateX(0%);\n        transform: translateX(0%);\n    }\n}\n\n\n\n.mcd-menu li ul,\n.mcd-menu li ul li ul {\n  position: absolute;\n  height: auto;\n  min-width: 200px;\n  padding: 0;\n  margin: 0;\n  background: #FFF;\n  /*border-top: 4px solid #e67e22;*/\n  opacity: 0;\n  visibility: hidden;\n  transition: all 300ms linear;\n  -o-transition: all 300ms linear;\n  -ms-transition: all 300ms linear;\n  -moz-transition: all 300ms linear;\n  -webkit-transition: all 300ms linear;\n  /*top: 130px;*/\n  z-index: 1000;\n  \n  /* == */\n  left:280px;\n  top: 0px;\n  border-left: 4px solid #e67e22;\n  /* == */\n}\n.mcd-menu li ul:before {\n  content: \"\";\n  position: absolute;\n  /*top: -8px;\n  left: 23%;\n  border-bottom: 5px solid #e67e22;\n  border-left: 5px solid transparent;\n  border-right: 5px solid transparent;*/\n  \n  /* == */\n  top: 25px;\n  left: -9px;\n  border-right: 5px solid #e67e22;\n  border-bottom: 5px solid transparent;\n  border-top: 5px solid transparent;\n  /* == */\n}\n.mcd-menu li:hover > ul,\n.mcd-menu li ul li:hover > ul {\n  display: block;\n  opacity: 1;\n  visibility: visible;\n  /*top: 100px;*/\n  \n  /* == */\n  left:250px;\n  /* == */\n}\n/*.mcd-menu li ul li {\n  float: none;\n}*/\n.mcd-menu li ul li a {\n  padding: 10px;\n  text-align: left;\n  border: 0;\n  border-bottom: 1px solid #EEE;\n  \n  /* == */\n  height: auto;\n  /* == */\n}\n.mcd-menu li ul li a i {\n  font-size: 16px;\n  display: inline-block;\n  margin: 0 10px 0 0;\n}\n.mcd-menu li ul li ul {\n  left: 230px;\n  top: 0;\n  border: 0;\n  border-left: 4px solid #e67e22;\n}  \n.mcd-menu li ul li ul:before {\n  content: \"\";\n  position: absolute;\n  top: 15px;\n  /*left: -14px;*/\n  /* == */\n  left: -9px;\n  /* == */\n  border-right: 5px solid #e67e22;\n  border-bottom: 5px solid transparent;\n  border-top: 5px solid transparent;\n}\n.mcd-menu li ul li:hover > ul {\n  top: 0px;\n  left: 200px;\n}\n\n\n\n/*.mcd-menu li.float {\n  float: right;\n}*/\n.mcd-menu li a.search {\n  /*padding: 29px 20px 30px 10px;*/\n  padding: 10px 10px 15px 10px;\n  clear: both;\n}\n.mcd-menu li a.search i {\n  margin: 0;\n  display: inline-block;\n  font-size: 18px;\n}\n.mcd-menu li a.search input {\n  border: 1px solid #EEE;\n  padding: 10px;\n  background: #FFF;\n  outline: none;\n  color: #777;\n  \n  /* == */\n  width:170px;\n  float:left;\n  /* == */\n}\n.mcd-menu li a.search button {\n  border: 1px solid #e67e22;\n  /*padding: 10px;*/\n  background: #e67e22;\n  outline: none;\n  color: #FFF;\n  margin-left: -4px;\n  \n  /* == */\n  float:left;\n  padding: 10px 10px 11px 10px;\n  /* == */\n}\n.mcd-menu li a.search input:focus {\n  border: 1px solid #e67e22;\n}\n\n\n.search-mobile { \n	display:none !important;\n	background:#e67e22;\n	border-left:1px solid #e67e22;\n	border-radius:0 3px 3px 0;\n}\n.search-mobile i { \n	color:#FFF; \n	margin:0 !important;\n}\n\n\n@media only screen and (min-width: 960px) and (max-width: 1199px) {\n    .mcd-menu {\n		margin-left:10px;\n	}\n}\n\n@media only screen and (min-width: 768px) and (max-width: 959px) {\n    .mcd-menu {\n		width: 200px;\n	}\n	.mcd-menu li a {\n		height:30px;\n	}\n	.mcd-menu li a i {\n		font-size: 22px;\n	}\n	.mcd-menu li a strong {\n		font-size: 12px;\n	}\n	.mcd-menu li a small {\n		font-size: 10px;\n	}	\n	.mcd-menu li a.search input {\n		width: 120px;\n		font-size: 12px;\n	}\n	.mcd-menu li a.search buton{\n		padding: 8px 10px 9px 10px;\n	}\n	.mcd-menu li > ul {\n		min-width:180px;\n	}\n	.mcd-menu li:hover > ul {\n		min-width:180px;\n		left:200px;\n	}\n	.mcd-menu li ul li > ul, .mcd-menu li ul li ul li > ul {\n		min-width:150px;\n	}\n	.mcd-menu li ul li:hover > ul {\n		left:180px;\n		min-width:150px;\n	}\n	.mcd-menu li ul li ul li:hover > ul {\n		left:150px;\n		min-width:150px;\n	}\n	.mcd-menu li ul a {\n		font-size:12px;\n	}\n	.mcd-menu li ul a i {\n		font-size:14px;\n	}\n}\n\n@media only screen and (min-width: 480px) and (max-width: 767px) {\n	\n	.mcd-menu { \n		width: 50px;\n	}\n	.mcd-menu li a { \n		position: relative;\n		padding: 12px 16px;\n		height:20px;\n	}\n	.mcd-menu li a small { \n		display: none;\n	}\n	.mcd-menu li a strong { \n		display: none;\n	}\n	.mcd-menu li a:hover strong,.mcd-menu li a.active strong {\n		display:block;\n		font-size:10px;\n		padding:3px 0;\n		position:absolute;\n		bottom:0px;\n		left:0;\n		background:#e67e22;\n		color:#FFF;\n		min-width:100%;\n		text-transform:lowercase;\n		font-weight:normal;\n		text-align:center;\n	}\n	.mcd-menu li .search { \n		display: none;\n	}\n	\n	.mcd-menu li > ul {\n		min-width:180px;\n		left:70px;\n	}\n	.mcd-menu li:hover > ul {\n		min-width:180px;\n		left:50px;\n	}\n	.mcd-menu li ul li > ul, .mcd-menu li ul li ul li > ul {\n		min-width:150px;\n	}\n	.mcd-menu li ul li:hover > ul {\n		left:180px;\n		min-width:150px;\n	}\n	.mcd-menu li ul li ul li > ul {\n		left:35px;\n		top: 45px;\n		border:0;\n		border-top:4px solid #e67e22;\n	}\n	.mcd-menu li ul li ul li > ul:before {\n		left:30px;\n		top: -9px;\n		border:0;\n		border-bottom:5px solid #e67e22;\n		border-left:5px solid transparent;\n		border-right:5px solid transparent;\n	}\n	.mcd-menu li ul li ul li:hover > ul {\n		left:30px;\n		min-width:150px;\n		top: 35px;\n	}\n	.mcd-menu li ul a {\n		font-size:12px;\n	}\n	.mcd-menu li ul a i {\n		font-size:14px;\n	}\n	\n}\n\n@media only screen and (max-width: 479px) {\n    .mcd-menu { \n		width: 50px;\n	}\n	.mcd-menu li a { \n		position: relative;\n		padding: 12px 16px;\n		height:20px;\n	}\n	.mcd-menu li a small { \n		display: none;\n	}\n	.mcd-menu li a strong { \n		display: none;\n	}\n	.mcd-menu li a:hover strong,.mcd-menu li a.active strong {\n		display:block;\n		font-size:10px;\n		padding:3px 0;\n		position:absolute;\n		bottom:0px;\n		left:0;\n		background:#e67e22;\n		color:#FFF;\n		min-width:100%;\n		text-transform:lowercase;\n		font-weight:normal;\n		text-align:center;\n	}\n	.mcd-menu li .search { \n		display: none;\n	}\n	\n	.mcd-menu li > ul {\n		min-width:180px;\n		left:70px;\n	}\n	.mcd-menu li:hover > ul {\n		min-width:180px;\n		left:50px;\n	}\n	.mcd-menu li ul li > ul, .mcd-menu li ul li ul li > ul {\n		min-width:150px;\n	}\n	.mcd-menu li ul li:hover > ul {\n		left:180px;\n		min-width:150px;\n	}\n	.mcd-menu li ul li ul li > ul {\n		left:35px;\n		top: 45px;\n		border:0;\n		border-top:4px solid #e67e22;\n	}\n	.mcd-menu li ul li ul li > ul:before {\n		left:30px;\n		top: -9px;\n		border:0;\n		border-bottom:5px solid #e67e22;\n		border-left:5px solid transparent;\n		border-right:5px solid transparent;\n	}\n	.mcd-menu li ul li ul li:hover > ul {\n		left:30px;\n		min-width:150px;\n		top: 35px;\n	}\n	.mcd-menu li ul a {\n		font-size:12px;\n	}\n	.mcd-menu li ul a i {\n		font-size:14px;\n	}\n    \n}', 0, 'Mw==', '', '6', 1, '2024-07-08 21:14:32', '2024-07-08 21:15:10', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
