('8MFC1#2#2#5#1#1', '(html) bulat / round', '<label className=\"w3-switch\"  >\n                            <input type=\'checkbox\'></input>\n                            <span className=\"slider round\"></span>\n                        </label>', 0, 'Mw==', '', '6', 1, '2024-07-13 00:21:10', '2024-07-13 00:23:42', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#2#5#1#2', '(html) kotak', '<label className=\"w3-switch\" style={{transform:\"rotate(90deg)\"}}>\n                            <input type=\'checkbox\' checked={onOff} onChange={actOnOff}></input>\n                            <span className=\"slider\"></span>\n                        </label>', 0, 'Mw==', '', '6', 1, '2024-07-13 00:21:56', '2024-07-13 00:21:56', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#2#5#1#3', 'css', '.w3-switch {\n  position: relative;\n  display: inline-block;\n  width: 60px;\n  height: 34px;\n\n  & .slider {\n    position: absolute;\n    cursor: pointer;\n    top: 0;\n    left: 0;\n    right: 0;\n    bottom: 0;\n    background-color: #ccc;\n    -webkit-transition: .4s;\n    transition: .4s;\n  }\n  \n  & .slider:before {\n    position: absolute;\n    content: \"\";\n    height: 26px;\n    width: 26px;\n    left: 4px;\n    bottom: 4px;\n    background-color: white;\n    -webkit-transition: .4s;\n    transition: .4s;\n  }\n  & input:checked + .slider {\n    background-color: #0015ff;\n  }\n  \n  & input:focus + .slider {\n    box-shadow: 0 0 1px #0015ff;\n  }\n  \n  & input:checked + .slider:before {\n    -webkit-transform: translateX(26px);\n    -ms-transform: translateX(26px);\n    transform: translateX(26px);\n  }\n  & .slider.round {\n    border-radius: 34px;\n  }\n  \n  & .slider.round:before {\n    border-radius: 50%;\n  }\n  & input {\n    opacity: 0;\n    width: 0;\n    height: 0;\n  }\n}', 0, 'Mw==', '', '6', 1, '2024-07-13 00:22:28', '2024-07-13 00:22:28', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#2#5#2', 'slimen mami switch form', 'menampilkan form seperti login register', 0, 'Mw==', '', '5', 1, '2024-07-14 15:41:37', '2024-07-14 15:41:37', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#2#5#2#1', '(html) form Login & Register', '<div class=\"SM-sw-form-body\" style=\"min-height: 95vh;\">\n    <div class=\"SM-sw-form\" style=\"height: 600px; border-radius: 0px 10px 10px 0px\">  	\n        <input type=\"checkbox\" id=\"chk\" aria-hidden=\"true\" checked/> \n            <div class=\"signup\">\n                <form > \n                    <label for=\"chk\" aria-hidden=\"true\">Register</label> \n                    <input id=\"name\" placeholder=\"Nama\" type=\"text\" autofocus/> \n                    <input id=\"email\" placeholder=\"Email\"  type=\"email\" required autocomplete=\"email\"/> \n                    <input id=\"password\" placeholder=\"Password\"  type=\"password\"required autocomplete=\"new-password\"/> \n                    <input id=\"password-confirm\" placeholder=\"Password Confirm\"  required autocomplete=\"new-password\">\n                    <button type=\"submit\" >Register</button>\n                </form>\n            </div>\n\n            <div class=\"login\" > \n                <form > \n                    <label for=\"chk\" aria-hidden=\"true\">Login</label>\n                    <input id=\"email\" placeholder=\"Email\"  type=\"email\"  required autocomplete=\"email\" autofocus/> \n                    <input id=\"password\" placeholder=\"Password\"  type=\"password\"  required autocomplete=\"current-password\"/> \n                    <button type=\"submit\" >Login</button> \n                    <div class=\"jcE\">\n                        <a class=\"btn btn-link\" href=\"#\">\n                            Forgot Your Password?\n                        </a>\n                    </div> \n                </form>\n            </div>\n    </div>\n</div>', 0, 'Mw==', '', '6', 1, '2024-07-14 15:42:49', '2024-07-14 15:46:02', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', '');
