('8MFC1#2#2#5#2#2', 'css', '.SM-sw-form-body{\n	margin: 0;\n	padding: 0;\n	display: flex;\n	justify-content: center;\n	align-items: center;\n	min-height: 100vh;\n	font-family: \'Jost\', sans-serif;\n  background: linear-gradient(to top, #28a745, #347a96);\n	// background: linear-gradient(to bottom, #0f0c29, #302b63, #24243e);\n  & .SM-sw-form{\n    width: 350px;\n    height: 600px;\n    // background: red;\n    overflow: hidden;\n    // background: url(\"https://doc-08-2c-docs.googleusercontent.com/docs/securesc/68c90smiglihng9534mvqmq1946dmis5/fo0picsp1nhiucmc0l25s29respgpr4j/1631524275000/03522360960922298374/03522360960922298374/1Sx0jhdpEpnNIydS4rnN4kHSJtU1EyWka?e=view&authuser=0&nonce=gcrocepgbb17m&user=03522360960922298374&hash=tfhgbs86ka6divo3llbvp93mg4csvb38\") no-repeat center/ cover;\n    border-radius: 10px;\n    box-shadow: 5px 20px 50px #000;\n  \n    & #chk{\n      display: none;\n    }\n    & .signup{\n      position: relative;\n      width:100%;\n      height: 100%;\n    }\n    & label{\n      color: #fff;\n      font-size: 2.3em;\n      justify-content: center;\n      display: flex;\n      margin: 50px;\n      font-weight: bold;\n      cursor: pointer;\n      transition: .5s ease-in-out;\n    }\n    & input{\n      width: 80%;\n      // height: 10px;\n      background: #e0dede;\n      justify-content: center;\n      display: flex;\n      margin: 20px auto;\n      padding: 12px;\n      border: none;\n      outline: none;\n      border-radius: 5px;\n    }\n    & button{\n      width: 60%;\n      height: 40px;\n      margin: 10px auto;\n      justify-content: center;\n      display: block;\n      color: #fff;\n      background: #573b8a;\n      font-size: 1em;\n      font-weight: bold;\n      margin-top: 30px;\n      outline: none;\n      border: none;\n      border-radius: 5px;\n      transition: .2s ease-in;\n      cursor: pointer;\n    }\n    & button:hover{\n      background: #6d44b8;\n    }\n    & .login{\n      height: 560px;\n      background: #eee;\n      border-radius: 60% / 10%;\n      transform: translateY(-180px);\n      transition: .8s ease-in-out;\n    }\n    & .login label{\n      color: #573b8a;\n      transform: scale(.6);\n    }\n    \n    & #chk:checked ~ .login{\n      transform: translateY(-580px);\n    }\n    & #chk:checked ~ .login label{\n      transform: scale(1);	\n    }\n    & #chk:checked ~ .signup label{\n      transform: scale(.6);\n    }\n  }\n}', 0, 'Mw==', '', '6', 1, '2024-07-14 15:42:59', '2024-07-14 15:42:59', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
