('8MFC1#2#2#6#1', '(html)bweb_informasi / bappeda web informasi', '<div class=\"bweb_informasi\" style=\"background-image: url(\'http://localhost:8000/1.jpg\'); background-size: cover;\">\n            <div class=\"bweb_informasi alfaCoklat \">\n                <div class=\"w80p mauto\">\n                    <div class=\"menuLogo\">\n                        <img src=\"http://localhost:8000/logoKSB.png\">\n                        <a id=\"menu\">☰</a>\n                    </div>\n\n                    <div class=\"flexC brand justifySA\">\n                        <label class=\"judul fpacifico cwarning\">Bappeda</label>\n                        <label class=\"subjudul fPoppins\">badan perencanaan dan pembangunan daerah</label>\n                        <label class=\"judul fPoppins\">kabupaten Sumbawa barat</label>\n                    </div>\n\n                    <div class=\"informasi\" style=\"display:none\"> \n                        <label class=\"\">\n                            <span>Lokasi</span> <br> jl. Bung Karno No. 5 Komplek KTC - Taliwang <br>\n                            kabupaten Sumbawa barat\n                        </label>\n                        <label class=\"\">\n                            <span>Email</span> <br><u>Sekretariatbappedaksb@gmail.com </u> <br>\n                            <span>Kode Pos </span> : 84455 <br>\n                            <span>Tlp</span> : (0372) 8182595\n                        </label>\n                        <ul id=\"sosial\">\n                            <li><a href=\"\"><span class=\"mdi mdi-instagram\"></span> @bappedaKSB</a></li>\n                            <li><a href=\"https://bappedaKSB.com\" target=\"_blank\"><span class=\"mdi mdi-web\"></span> bappedaKSB</a></li>\n                            <li><a href=\"\"><span class=\"mdi mdi-youtube\"></span> @bappedaKSB</a></li>\n                        </ul>\n                    </div>\n                </div>\n            </div>\n        </div>', 0, 'Mw==', '', '5', 1, '2024-07-16 05:04:48', '2024-07-16 05:27:16', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#2#6#2', '(css)bweb_informasi CSS', '.bweb_informasi{ \n    height: 100vh;\n    min-height: 600px;\n    & .menuLogo{\n        height: 150px;\n        @extend .pwrap-10, .jcSE, .aiC, .w60p;\n        & img{\n            height: 50%;\n        }\n    }\n    & .brand{\n        text-transform: uppercase; \n        font-weight: bold; \n        width: 100%;\n        margin-top: 10%;\n        & .judul{\n            color: map-get(_.$c,\'light\');\n            @extend .fzL3;\n        }\n        & .subjudul{ \n            color: map-get(_.$c,\'lightE\');\n            @extend .fzXl, .tbold;\n        }\n        & .subjudul1{ \n            color: map-get(_.$c,\'lightE1\');\n        }\n    }\n    & .informasi{\n        position: unset;\n        bottom: 0px;\n        display: grid;\n        width: 80%;\n        @extend .cwhite, .pwrap-10, .fzL, .alfaDark;\n        grid-template-columns: repeat(1, 100%);\n        grid-gap: 20px;\n        & span{\n            @extend .fPoppins,.cwarning, .fzXl;\n        }\n        & a{\n            @extend .cwhite;\n        }\n        #sosial{display: none}\n    }\n}\n\n@media only screen and (min-width: 650px){ \n    .bweb_informasi .informasi{\n        position: absolute;\n        grid-template-columns: repeat(3, 33%);\n    } \n}\n@media screen and (min-width: 800px) { \n    .bweb_informasi .menuLogo{\n        @include _.jc(space-between);\n        width: 100%;\n    }\n    .bweb_informasi .informasi #sosial{display: block}\n}', 0, 'Mw==', '', '5', 1, '2024-07-16 05:08:10', '2024-07-16 05:36:29', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
