('8MFC1#2#2#8#2', '(css)background and Color', '@use \'../abstracts/variabel\' as _;\n\n.bwhite{ @include _.cB(\'white\')}\n.cwhite{@include _.c(\'white\')}\n\n.blight{@include _.cB(\'light\'); @include _.c(\'dark\'); }\n.blight04{ background-color: rgba(map-get(_.$c,\'light\'), 0.4);}\n.blight08{ background-color: rgba(map-get(_.$c,\'light\'), 0.8);}\n.blightG-opa2{@include _.cGradient(left, rgba(map-get(_.$c,\'light\'),0), rgba(map-get(_.$c,\'light\'),0.8)); @extend .cwhite;}\n.blightG-opa2End{@include _.cGradient(right, rgba(map-get(_.$c,\'light\'),0), rgba(map-get(_.$c,\'light\'),0.8)); @extend .cwhite;}\n\n.clight{@include _.c(\'light\')}\n\n.bblack{@include _.cB(\'black\') }\n.cblack{@include _.c(\'black\')}\n\n.bprimary{@include _.cB(\'primary\'); @extend .cwhite; }\n.bprimary1{@include _.cB(\'primary1\'); @extend .cwhite; }\n.cprimary{@include _.c(\'primary\')}\n.bprimaryG-opa2{@include _.cGradient(left, rgba(map-get(_.$c,\'primary1\'),0.2), rgba(map-get(_.$c,\'primary\'),0.8)); @extend .cwhite;}\n.bprimaryG-opa2End{@include _.cGradient(right, rgba(map-get(_.$c,\'primary1\'),0.2), rgba(map-get(_.$c,\'primary\'),0.8)); @extend .cwhite;}\n\n\n.bwarning{@include _.cB(\'warning\'); @extend .cwhite;}\n.cwarning{@include _.c(\'warning\')}\n.bwarningG{@include _.cGradient(left, map-get(_.$c,\'warning\') ,map-get(_.$c,\'warning1\')); @extend .cwhite;}\n.bwarningG-opa2{@include _.cGradient(left, rgba(map-get(_.$c,\'warning1\'),0.2), rgba(map-get(_.$c,\'warning\'),0.8)); @extend .cwhite;}\n.bwarningG-opa2End{@include _.cGradient(right, rgba(map-get(_.$c,\'warning1\'),0.2), rgba(map-get(_.$c,\'warning\'),0.8)); @extend .cwhite;}\n.borderBWarning-1{border-bottom: 1px solid map-get(_.$c,\'warning1\');}\n.borderBWarning-5{border-bottom: 5px solid map-get(_.$c,\'warning1\');}\n\n.binfo{@include _.cB(\'info\'); @extend .cwhite;}\n.binfo1{@include _.cB(\'info1\'); @extend .cwhite;}\n.binfo3{@include _.cB(\'info3\'); @extend .cdark;}\n\n.binfoG{@include _.cGradient(left, map-