('8MFC1#2#2#9#1', '(html)form-style-10', '<div class=\"form-style-10\">\n<h1>Sign Up Now!<span>Sign up and tell us what you think of the site!</span></h1>\n<form>\n    <div class=\"section\"><span>1</span>First Name & Address</div>\n    <div class=\"inner-wrap\">\n        <label>Your Full Name <input type=\"text\" name=\"field1\" /></label>\n        <label>Address <textarea name=\"field2\"></textarea></label>\n    </div>\n\n    <div class=\"section\"><span>2</span>Email & Phone</div>\n    <div class=\"inner-wrap\">\n        <label>Email Address <input type=\"email\" name=\"field3\" /></label>\n        <label>Phone Number <input type=\"text\" name=\"field4\" /></label>\n    </div>\n\n    <div class=\"section\"><span>3</span>Passwords</div>\n        <div class=\"inner-wrap\">\n        <label>Password <input type=\"password\" name=\"field5\" /></label>\n        <label>Confirm Password <input type=\"password\" name=\"field6\" /></label>\n    </div>\n    <div class=\"button-section\">\n     <input type=\"submit\" name=\"Sign Up\" />\n     <span class=\"privacy-policy\">\n     <input type=\"checkbox\" name=\"field7\">You agree to our Terms and Policy. \n     </span>\n    </div>\n</form>\n</div>', 0, 'Mw==', '', '5', 1, '2024-07-16 06:19:25', '2024-07-16 06:20:38', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#2#9#2', '(css)form-style-10', '.form-style-10{\n	width:450px;\n	padding:30px;\n	margin:40px auto;\n	background: #FFF;\n	border-radius: 10px;\n	-webkit-border-radius:10px;\n	-moz-border-radius: 10px;\n	box-shadow: 0px 0px 10px rgba(0, 0, 0, 0.13);\n	-moz-box-shadow: 0px 0px 10px rgba(0, 0, 0, 0.13);\n	-webkit-box-shadow: 0px 0px 10px rgba(0, 0, 0, 0.13);\n}\n.form-style-10 .inner-wrap{\n	padding: 30px;\n	background: #F8F8F8;\n	border-radius: 6px;\n	margin-bottom: 15px;\n}\n.form-style-10 h1{\n	background: #2A88AD;\n	padding: 20px 30px 15px 30px;\n	margin: -30px -30px 30px -30px;\n	border-radius: 10px 10px 0 0;\n	-webkit-border-radius: 10px 10px 0 0;\n	-moz-border-radius: 10px 10px 0 0;\n	color: #fff;\n	text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.12);\n	font: normal 30px \'Bitter\', serif;\n	-moz-box-shadow: inset 0px 2px 2px 0px rgba(255, 255, 255, 0.17);\n	-webkit-box-shadow: inset 0px 2px 2px 0px rgba(255, 255, 255, 0.17);\n	box-shadow: inset 0px 2px 2px 0px rgba(255, 255, 255, 0.17);\n	border: 1px solid #257C9E;\n}\n.form-style-10 h1 > span{\n	display: block;\n	margin-top: 2px;\n	font: 13px Arial, Helvetica, sans-serif;\n}\n.form-style-10 label{\n	display: block;\n	font: 13px Arial, Helvetica, sans-serif;\n	color: #888;\n	margin-bottom: 15px;\n}\n.form-style-10 input[type=\"text\"],\n.form-style-10 input[type=\"date\"],\n.form-style-10 input[type=\"datetime\"],\n.form-style-10 input[type=\"email\"],\n.form-style-10 input[type=\"number\"],\n.form-style-10 input[type=\"search\"],\n.form-style-10 input[type=\"time\"],\n.form-style-10 input[type=\"url\"],\n.form-style-10 input[type=\"password\"],\n.form-style-10 textarea,\n.form-style-10 select {\n	display: block;\n	box-sizing: border-box;\n	-webkit-box-sizing: border-box;\n	-moz-box-sizing: border-box;\n	width: 100%;\n	padding: 8px;\n	border-radius: 6px;\n	-webkit-border-radius:6px;\n	-moz-border-radius:6px;\n	border: 2px solid #fff;\n	box-shadow: inset 0px 1px 1px rgba(0, 0, 0, 0.33);\n	-moz-box-shadow: inset 0px 1px 1px rgba(0, 0, 0, 0.33);\n	-webkit-box-shadow: inset 0px 1px 1px rgba(0, 0, 0, 0.33);\n}\n\n.form-style-10 .section{\n	font: normal 20px \'Bitter\', serif;\n	color: #2A88AD;\n	margin-bottom: 5px;\n}\n.form-style-10 .section span {\n	background: #2A88AD;\n	padding: 5px 10px 5px 10px;\n	position: absolute;\n	border-radius: 50%;\n	-webkit-border-radius: 50%;\n	-moz-border-radius: 50%;\n	border: 4px solid #fff;\n	font-size: 14px;\n	margin-left: -45px;\n	color: #fff;\n	margin-top: -3px;\n}\n.form-style-10 input[type=\"button\"], \n.form-style-10 input[type=\"submit\"]{\n	background: #2A88AD;\n	padding: 8px 20px 8px 20px;\n	border-radius: 5px;\n	-webkit-border-radius: 5px;\n	-moz-border-radius: 5px;\n	color: #fff;\n	text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.12);\n	font: normal 30px \'Bitter\', serif;\n	-moz-box-shadow: inset 0px 2px 2px 0px rgba(255, 255, 255, 0.17);\n	-webkit-box-shadow: inset 0px 2px 2px 0px rgba(255, 255, 255, 0.17);\n	box-shadow: inset 0px 2px 2px 0px rgba(255, 255, 255, 0.17);\n	border: 1px solid #257C9E;\n	font-size: 15px;\n}\n.form-style-10 input[type=\"button\"]:hover, \n.form-style-10 input[type=\"submit\"]:hover{\n	background: #2A6881;\n	-moz-box-shadow: inset 0px 2px 2px 0px rgba(255, 255, 255, 0.28);\n	-webkit-box-shadow: inset 0px 2px 2px 0px rgba(255, 255, 255, 0.28);\n	box-shadow: inset 0px 2px 2px 0px rgba(255, 255, 255, 0.28);\n}\n.form-style-10 .privacy-policy{\n	float: right;\n	width: 250px;\n	font: 12px Arial, Helvetica, sans-serif;\n	color: #4D4D4D;\n	margin-top: 10px;\n	text-align: right;\n}', 0, 'Mw==', '', '5', 1, '2024-07-16 06:19:57', '2024-07-16 06:20:31', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#2#9#3', '(html)form-style-7', '<form class=\"form-style-7\">\n<ul>\n<li>\n    <label for=\"name\">Name</label>\n    <input type=\"text\" name=\"name\" maxlength=\"100\">\n    <span>Enter your full name here</span>\n</li>\n<li>\n    <label for=\"email\">Email</label>\n    <input type=\"email\" name=\"email\" maxlength=\"100\">\n    <span>Enter a valid email address</span>\n</li>\n<li>\n    <label for=\"url\">Website</label>\n    <input type=\"url\" name=\"url\" maxlength=\"100\">\n    <span>Your website address (eg: http://www.google.com)</span>\n</li>\n<li>\n    <label for=\"bio\">About You</label>\n    <textarea name=\"bio\" onkeyup=\"adjust_textarea(this)\"></textarea>\n    <span>Say something about yourself</span>\n</li>\n<li>\n    <input type=\"submit\" value=\"Send This\" >\n</li>\n</ul>\n</form>', 0, 'Mw==', '', '5', 1, '2024-07-16 06:22:38', '2024-07-16 06:22:38', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#2#9#4', '(css)form-style-7', '.form-style-7{\n	max-width:400px;\n	margin:50px auto;\n	background:#fff;\n	border-radius:2px;\n	padding:20px;\n	font-family: Georgia, \"Times New Roman\", Times, serif;\n}\n.form-style-7 h1{\n	display: block;\n	text-align: center;\n	padding: 0;\n	margin: 0px 0px 20px 0px;\n	color: #5C5C5C;\n	font-size:x-large;\n}\n.form-style-7 ul{\n	list-style:none;\n	padding:0;\n	margin:0;	\n}\n.form-style-7 li{\n	display: block;\n	padding: 9px;\n	border:1px solid #DDDDDD;\n	margin-bottom: 30px;\n	border-radius: 3px;\n}\n.form-style-7 li:last-child{\n	border:none;\n	margin-bottom: 0px;\n	text-align: center;\n}\n.form-style-7 li > label{\n	display: block;\n	float: left;\n	margin-top: -19px;\n	background: #FFFFFF;\n	height: 14px;\n	padding: 2px 5px 2px 5px;\n	color: #B9B9B9;\n	font-size: 14px;\n	overflow: hidden;\n	font-family: Arial, Helvetica, sans-serif;\n}\n.form-style-7 input[type=\"text\"],\n.form-style-7 input[type=\"date\"],\n.form-style-7 input[type=\"datetime\"],\n.form-style-7 input[type=\"email\"],\n.form-style-7 input[type=\"number\"],\n.form-style-7 input[type=\"search\"],\n.form-style-7 input[type=\"time\"],\n.form-style-7 input[type=\"url\"],\n.form-style-7 input[type=\"password\"],\n.form-style-7 textarea,\n.form-style-7 select \n{\n	box-sizing: border-box;\n	-webkit-box-sizing: border-box;\n	-moz-box-sizing: border-box;\n	width: 100%;\n	display: block;\n	outline: none;\n	border: none;\n	height: 25px;\n	line-height: 25px;\n	font-size: 16px;\n	padding: 0;\n	font-family: Georgia, \"Times New Roman\", Times, serif;\n}\n.form-style-7 input[type=\"text\"]:focus,\n.form-style-7 input[type=\"date\"]:focus,\n.form-style-7 input[type=\"datetime\"]:focus,\n.form-style-7 input[type=\"email\"]:focus,\n.form-style-7 input[type=\"number\"]:focus,\n.form-style-7 input[type=\"search\"]:focus,\n.form-style-7 input[type=\"time\"]:focus,\n.form-style-7 input[type=\"url\"]:focus,\n.form-style-7 input[type=\"password\"]:focus,\n.form-style-7 textarea:focus,\n.form-style-7 select:focus \n{\n}\n.form-style-7 li > span{\n	background: #F3F3F3;\n	display: block;\n	padding: 3px;\n	margin: 0 -9px -9px -9px;\n	text-align: center;\n	color: #C0C0C0;\n	font-family: Arial, Helvetica, sans-serif;\n	font-size: 11px;\n}\n.form-style-7 textarea{\n	resize:none;\n}\n.form-style-7 input[type=\"submit\"],\n.form-style-7 input[type=\"button\"]{\n	background: #2471FF;\n	border: none;\n	padding: 10px 20px 10px 20px;\n	border-bottom: 3px solid #5994FF;\n	border-radius: 3px;\n	color: #D2E2FF;\n}\n.form-style-7 input[type=\"submit\"]:hover,\n.form-style-7 input[type=\"button\"]:hover{\n	background: #6B9FFF;\n	color:#fff;\n}', 0, 'Mw==', '', '5', 1, '2024-07-16 06:22:54', '2024-07-16 06:22:54', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#2#9#5', '(html)form-style-5', '<div class=\"form-style-5\">\n<form>\n<fieldset>\n<legend><span class=\"number\">1</span> Candidate Info</legend>\n<input type=\"text\" name=\"field1\" placeholder=\"Your Name *\">\n<input type=\"email\" name=\"field2\" placeholder=\"Your Email *\">\n<textarea name=\"field3\" placeholder=\"About yourself\"></textarea>\n<label for=\"job\">Interests:</label>\n<select id=\"job\" name=\"field4\">\n<optgroup label=\"Indoors\">\n  <option value=\"fishkeeping\">Fishkeeping</option>\n  <option value=\"reading\">Reading</option>\n  <option value=\"boxing\">Boxing</option>\n  <option value=\"debate\">Debate</option>\n  <option value=\"gaming\">Gaming</option>\n  <option value=\"snooker\">Snooker</option>\n  <option value=\"other_indoor\">Other</option>\n</optgroup>\n<optgroup label=\"Outdoors\">\n  <option value=\"football\">Football</option>\n  <option value=\"swimming\">Swimming</option>\n  <option value=\"fishing\">Fishing</option>\n  <option value=\"climbing\">Climbing</option>\n  <option value=\"cycling\">Cycling</option>\n  <option value=\"other_outdoor\">Other</option>\n</optgroup>\n</select>      \n</fieldset>\n<fieldset>\n<legend><span class=\"number\">2</span> Additional Info</legend>\n<textarea name=\"field3\" placeholder=\"About Your School\"></textarea>\n</fieldset>\n<input type=\"submit\" value=\"Apply\" />\n</form>\n</div>', 0, 'Mw==', '', '5', 1, '2024-07-16 06:24:36', '2024-07-16 06:25:15', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
