t-shadow: 0 1px 0 rgba(255,255,255,0.2);\n	border-radius: 15px 15px 15px 0px;\n}\n\n.form-style-5 input[type=\"submit\"],\n.form-style-5 input[type=\"button\"]\n{\n	position: relative;\n	display: block;\n	padding: 19px 39px 18px 39px;\n	color: #FFF;\n	margin: 0 auto;\n	background: #1abc9c;\n	font-size: 18px;\n	text-align: center;\n	font-style: normal;\n	width: 100%;\n	border: 1px solid #16a085;\n	border-width: 1px 1px 3px;\n	margin-bottom: 10px;\n}\n.form-style-5 input[type=\"submit\"]:hover,\n.form-style-5 input[type=\"button\"]:hover\n{\n	background: #109177;\n}', 0, 'Mw==', '', '5', 1, '2024-07-16 06:24:42', '2024-07-16 06:24:57', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
