('8MFC1#2#3#4#2#10', 'fetchData', 'async function fetchData() {\n    todoData.value = null\n    const res = await fetch(\n      `https://jsonplaceholder.typicode.com/todos/${todoId.value}`\n    )\n    todoData.value = await res.json()\n  }', 0, 'Mw==', '', '6', 1, '2024-08-10 15:13:22', '2024-08-10 15:13:22', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#3#4#2#11', 'Data Null and Preview', '<p v-if=\"!todoData\">Loading...</p>\n<pre v-else>{{ todoData }}</pre>\n <button @click=\"todoId++\" :disabled=\"!todoData\">Fetch', 0, 'Mw==', '', '6', 1, '2024-08-10 15:14:41', '2024-08-10 15:15:27', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
