('8MFC1#2#3#4#2#13', 'Emits', '<script setup>\n// declare emitted events\nconst emit = defineEmits([\'response\'])\n\n// emit with argument\nemit(\'response\', \'hello from child\')\n</script>\n\n\n<script setup>\nimport { ref } from \'vue\'\nimport ChildComp from \'./ChildComp.vue\'\n\nconst childMsg = ref(\'No child msg yet\')\n</script>\n\n<template>\n  <ChildComp @response=\"(msg) => childMsg = msg\" />\n  <p>{{ childMsg }}</p>\n</template>', 0, 'Mw==', '', '6', 1, '2024-08-10 15:23:59', '2024-08-10 15:23:59', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
