('8MFC1#2#3#4#2#15#12', 'Arguments', '<a v-bind:href=\"url\"> ... </a>\n\n<!-- shorthand -->\n<a :href=\"url\"> ... </a>\n\n\n<a v-on:click=\"doSomething\"> ... </a>\n\n<!-- shorthand -->\n<a @click=\"doSomething\"> ... </a>', 0, 'Mw==', '', '7', 1, '2024-08-10 15:32:13', '2024-08-10 15:32:33', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#3#4#2#15#13', 'Dynamic Arguments', '<!--\nNote that there are some constraints to the argument expression,\nas explained in the \"Dynamic Argument Value Constraints\" and \"Dynamic Argument Syntax Constraints\" sections below.\n-->\n<a v-bind:[attributeName]=\"url\"> ... </a>\n\n<!-- shorthand -->\n<a :[attributeName]=\"url\"> ... </a>\n\n\n<a v-on:[eventName]=\"doSomething\"> ... </a>\n\n<!-- shorthand -->\n<a @[eventName]=\"doSomething\"> ... </a>', 0, 'Mw==', '', '7', 1, '2024-08-10 15:32:58', '2024-08-10 15:32:58', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#3#4#2#15#14', 'Dynamic Argument Syntax Constraints', '<!-- This will trigger a compiler warning. -->\n<a :[\'foo\' + bar]=\"value\"> ... </a>\n\n<a :[someAttr]=\"value\"> ... </a>', 0, 'Mw==', '', '7', 1, '2024-08-10 15:33:22', '2024-08-10 15:33:47', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
