('8MFC1#2#3#4#2#15#5', 'Same-name Shorthand', '<!-- same as :id=\"id\" -->\n<div :id></div>\n\n<!-- this also works -->\n<div v-bind:id></div>', 0, 'Mw==', '', '7', 1, '2024-08-10 15:30:18', '2024-08-10 15:30:18', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
