('8MFC1#2#4#2#2', 'buat Componen ViewerComponent', 'import {  useRef } from \"react\"; \nimport html2pdf from \'html2pdf.js\';\n\nexport default function ViewerComponent({ dokumen }) { \n  const options = {\n    filename: dokumen,\n    margin: 1,\n    image: { type: \'jpeg\', quality: 0.98 },\n    html2canvas: { scale: 2 },\n    jsPDF: { unit: \'in\', format: \'letter\', orientation: \'portrait\' },\n  };\n  const contentRef = useRef(null);\n\n  const convertToPdf = () => {\n    const content = contentRef.current;\n    html2pdf().set(options).from(content).save();\n  }; \n\n  // return <div id=\"pspdfkit\" style=\"width: 100%; height: 100vh;\"></div> ;\n  return (\n    <div>\n      <div ref={contentRef}>\n        {/* Your HTML content that you want to convert to PDF */}\n        <h1>Hello, PDF!</h1>\n        <p>\n          This is a simple example of HTML-to-PDF conversion using\n          React and html2pdf.\n        </p>\n      </div>\n      <button onClick={convertToPdf}>Convert to PDF</button>\n    </div>\n  );\n}', 0, 'Mw==', '', '5', 1, '2024-07-09 19:46:56', '2024-07-09 19:46:56', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#2#4#2#3', 'penggunaan componen', '<div className=\"App\">\n			<div className=\"PDF-viewer\">\n               <ViewerComponent dokumen=\"http://localhost:8000/storage/2024-07-08-12-11-54am-1.ApaituC.pdf\"></ViewerComponent>\n			</div>\n		</div>', 0, 'Mw==', '', '5', 1, '2024-07-09 19:47:21', '2024-07-09 19:47:21', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
