('8MFC1#4#2#1#1', 'connect to sql server', 'npm install --save @nestjs/typeorm typeorm mssql\n\nimport { Module } from \'@nestjs/common\';\nimport { TypeOrmModule } from \'@nestjs/typeorm\';\n\n@Module({\n  imports: [\n    TypeOrmModule.forRoot({\n      type: \'mssql\',\n      host: \'localhost\', // or your server IP address\n      port: 1433, // default port for SQL Server\n      username: \'YOUR_USERNAME\',\n      password: \'YOUR_PASSWORD\',\n      database: \'YOUR_DATABASE_NAME\',\n      entities: [__dirname + \'/**/*.entity{.ts,.js}\'],\n      synchronize: true, // use this only in development\n    }),\n  ],\n})\nexport class AppModule {}', 0, 'Mw==', '', '5', 1, '2024-08-23 10:25:50', '2024-08-23 10:25:50', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#4#2#1#2', '(ol)CRUD API', 'nest g module note   / nest g module table/user\nnest g service note --no-spec\nnest g controller note --no-spec\ntambahan\nnote.entity.ts\nnote.module.ts', 0, 'Mw==', '', '5', 1, '2024-08-23 12:28:02', '2024-08-23 12:31:24', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#4#2#1#3', 'create Entity', '@PrimaryGeneratedColumn(\'uuid\')\nid: string;\n\n@Column({ name: \'title\', length: 60, nullable: false })\n@PrimaryColumn({ comment: \'Classifier Code\' })', 0, 'Mw==', '', '5', 1, '2024-08-23 12:38:01', '2024-08-23 12:38:01', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#4#2#1#4', 'Hot reload', 'npm i --save-dev webpack-node-externals run-script-webpack-plugin webpack\n\n\"start:dev\": \"nest build --webpack --webpackPath webpack-hmr.config.js --watch\"', 0, 'Mw==', '', '5', 1, '2024-08-23 14:48:50', '2024-08-23 14:48:50', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
('8MFC1#4#2#1#5', 'Solution to Enable CORS in NestJS', 'npm install @nestjs/platform-express cors\nimport * as cors from \'cors\';\n app.use(cors()); // Enable all origins\natau\nconst corsOptions = {\n  origin: [\'http://localhost\', \'http://anotherdomain.com\'], // Add allowed origins here\n  methods: \'GET,HEAD,PUT,PATCH,POST,DELETE\',\n  credentials: true,\n  optionsSuccessStatus: 204,\n};\n\napp.use(cors(corsOptions));', 0, 'Mw==', '', '5', 1, '2024-08-23 23:55:05', '2024-08-23 23:55:05', '1', '1', 'eyJ4Y2F0YXRhbiI6MCwieGZvcm1VcGxvYWQiOjAsInhmb3JtRW50cmkiOjB9', ''),
